const updateEnvironment = `-- name: UpdateEnvironment :one
UPDATE environments
SET name = $1, description = $2, config = $3, secret_enc = $4, status = $5,
    is_default = CASE WHEN $5::text = 'active' THEN is_default ELSE false END, updated_at = $6
WHERE company_id = $7 AND id = $8
RETURNING id, company_id, slug, name, description, driver, status, config, secret_enc, is_default, last_probe_at, last_probe_ok, last_probe_report, created_by_type, created_by_id, created_at, updated_at
`

type UpdateEnvironmentParams struct {
	Name        string
	Description string
	Config      []byte
	SecretEnc   string
	Status      string
	Now         time.Time
	CompanyID   uuid.UUID
	ID          uuid.UUID
}

func (q *Queries) UpdateEnvironment(ctx context.Context, arg UpdateEnvironmentParams) (Environment, error) {
	row := q.db.QueryRow(ctx, updateEnvironment,
		arg.Name,
		arg.Description,
		arg.Config,
		arg.SecretEnc,
		arg.Status,
		arg.Now,
		arg.CompanyID,
		arg.ID,
	)
	var i Environment
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.Slug,
		&i.Name,
		&i.Description,
		&i.Driver,
		&i.Status,
		&i.Config,
		&i.SecretEnc,
		&i.IsDefault,
		&i.LastProbeAt,
		&i.LastProbeOk,
		&i.LastProbeReport,
		&i.CreatedByType,
		&i.CreatedByID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
